void Solver::rephase() {
    rephases = 0;
    threshold = (int)(threshold * 0.85);
    rephase_limit += 4096 + (int)(conflicts * 0.001);
    // Diversify the saved phases based on rephase count
    int phase_type = (int)(slow_lbd_sum / conflicts) % 4;
    if (phase_type == 0) {
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if (phase_type == 1) {
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if (phase_type == 2) {
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else {
        // Keep current saved phases (phase saving)
    }
}
